export type IllosSigninAlertProps = {
  title?: string;
  description?: string;
  device?: string;
  location?: string;
  ip?: string;
  time?: string;
  /** Where the password reset link goes once the account is locked. */
  email?: string;
  /** Linked from the locked state. */
  activityHref?: string;
  onTrust?: () => void;
  /** Called when the lock is confirmed. Return a promise to show the locking state until it settles. */
  onLock?: () => void | Promise<void>;
  className?: string;
};

type Step = "ask" | "confirm" | "locking" | "locked" | "trusted";

const BTN =
  "relative inline-flex h-10 items-center justify-center gap-2 rounded-lg px-4 text-sm font-medium whitespace-nowrap select-none transition-[transform,background-color,color,box-shadow] duration-150 ease-out active:scale-[0.97] disabled:pointer-events-none disabled:opacity-60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring sm:h-9";
const PRIMARY = cx(BTN, "bg-primary text-primary-foreground hover:bg-primary/90");
const OUTLINE = cx(BTN, "bg-card shadow-[inset_0_0_0_1px_var(--color-border)] hover:bg-muted");
const DANGER = cx(BTN, "bg-[var(--danger)] text-white hover:bg-[color-mix(in_oklab,var(--danger)_88%,black)]");

export function IllosSigninAlert({
  title = "New sign-in from an unrecognized device",
  description = "If this was you, there's nothing else to do. If it wasn't, lock your account and we'll sign everyone out.",
  device = "Mac, Chrome 131",
  location = "Lisbon, Portugal",
  ip = "84.92.13.207",
  time = "Today at 09:42",
  email = "n••••@company.com",
  activityHref = "#",
  onTrust,
  onLock,
  className,
}: IllosSigninAlertProps) {
  const uid = useId();
  const [step, setStep] = useState<Step>("ask");
  const [failed, setFailed] = useState(false);
  const actions = useRef<HTMLDivElement>(null);
  const moved = useRef(false);
  const from = useRef<Step>("ask"); // the step before this one, so going back focuses the button that left it

  // The clicked button leaves with each step, so focus goes to the new step's main control instead of the page.
  useEffect(() => {
    if (!moved.current) return void (moved.current = true);
    if (step !== "locking") actions.current?.querySelector<HTMLElement>("[data-focus]")?.focus();
    from.current = step;
  }, [step]);

  const lock = async () => {
    setStep("locking");
    setFailed(false);
    try {
      await onLock?.();
      setStep("locked");
    } catch {
      setFailed(true);
      setStep("confirm");
    }
  };

  const details = [
    ["Device", device],
    ["Location", location],
    ["IP address", ip],
    ["Time", time],
  ] as const;

  return (
    <section
      className={cx(
        "grid w-full max-w-[860px] gap-1.5 rounded-2xl bg-card p-1.5 text-card-foreground md:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]",
        "shadow-[0_0_0_1px_rgb(0_0_0/0.06),0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.18)] dark:shadow-[0_0_0_1px_rgb(255_255_255/0.09)] antialiased",
        "[--danger:var(--color-destructive,oklch(0.6_0.21_25))]",
        className,
      )}
    >
      <HudWell svg={THREAT_SVG} className="aspect-[16/10] rounded-[10px] md:aspect-auto md:min-h-full" artClassName="[&>svg]:-translate-x-[4%] [&>svg]:scale-[1.08]" />

      <div className="flex flex-col px-3.5 pt-4 pb-4 sm:px-5 sm:pt-5 md:py-6 md:pr-6 md:pl-5">
        <h3 className="text-lg leading-snug font-medium text-balance">{title}</h3>
        <p className="mt-1.5 max-w-[46ch] text-sm leading-relaxed text-pretty text-muted-foreground">{description}</p>

        <dl className="mt-5 grid grid-cols-[auto_minmax(0,1fr)] gap-x-6 gap-y-2.5 rounded-xl bg-muted/70 px-4 py-3.5 text-sm dark:bg-muted/50">
          {details.map(([k, v]) => (
            <div key={k} className="contents">
              <dt className="text-muted-foreground">{k}</dt>
              <dd className="min-w-0 truncate tabular-nums">{v}</dd>
            </div>
          ))}
        </dl>

        <div ref={actions} className="mt-5 md:mt-auto md:pt-5">
          {step === "ask" && (
            <div className="flex flex-wrap gap-2.5">
              <button
                type="button"
                data-focus={from.current === "trusted" ? "" : undefined}
                className={PRIMARY}
                onClick={() => {
                  setStep("trusted");
                  onTrust?.();
                }}
              >
                This was me
              </button>
              <button
                type="button"
                data-focus={from.current === "confirm" ? "" : undefined}
                className={cx(OUTLINE, "text-[var(--danger)]")}
                onClick={() => setStep("confirm")}
              >
                Lock account
              </button>
            </div>
          )}

          {(step === "confirm" || step === "locking") && (
            <div
              role="group"
              aria-labelledby={`${uid}-lock`}
              onKeyDown={(e) => e.key === "Escape" && step === "confirm" && setStep("ask")}
              className="rounded-xl bg-[color-mix(in_oklab,var(--danger)_7%,var(--color-card))] p-4 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--danger)_28%,transparent)]"
            >
              <p id={`${uid}-lock`} className="text-sm font-medium">
                Lock your account?
              </p>
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
                Every session is signed out, including this one. We'll email a link to set a new password.
              </p>
              {failed && (
                <p role="alert" className="mt-2 text-sm text-[var(--danger)]">
                  We couldn't lock the account. Check your connection and try again.
                </p>
              )}
              <div className="mt-3.5 flex flex-wrap gap-2">
                <button type="button" data-focus className={OUTLINE} disabled={step === "locking"} onClick={() => setStep("ask")}>
                  Cancel
                </button>
                <button type="button" className={DANGER} disabled={step === "locking"} onClick={lock}>
                  {step === "locking" ? "Locking…" : "Lock account"}
                </button>
              </div>
            </div>
          )}

          {step === "locked" && (
            <div role="status" className="flex items-start gap-3">
              <Badge tone="var(--danger)">
                <path d="M7 11V8a5 5 0 0 1 10 0v3" />
                <rect x="5" y="11" width="14" height="10" rx="2" />
              </Badge>
              <div className="min-w-0">
                <p className="text-sm font-medium">Account locked</p>
                <p className="mt-0.5 text-sm leading-relaxed text-muted-foreground">
                  Every session is signed out. A reset link is on its way to {email}.
                </p>
                <a href={activityHref} data-focus className="mt-2 inline-block rounded-sm text-sm font-medium underline underline-offset-4 decoration-[color-mix(in_oklab,currentColor_35%,transparent)] hover:decoration-current focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">
                  Review recent activity
                </a>
              </div>
            </div>
          )}

          {step === "trusted" && (
            <div role="status" className="flex items-start gap-3">
              <Badge tone="var(--color-chart-2, oklch(0.65 0.12 180))">
                <path d="M20 6 9 17l-5-5" />
              </Badge>
              <div className="min-w-0">
                <p className="text-sm font-medium">Thanks for confirming</p>
                <p className="mt-0.5 text-sm leading-relaxed text-muted-foreground">We'll remember this device and won't ask again.</p>
                <button
                  type="button"
                  data-focus
                  onClick={() => setStep("ask")}
                  className="relative mt-2 rounded-sm text-sm font-medium underline before:absolute before:-inset-x-2 before:-inset-y-2.5 underline-offset-4 decoration-[color-mix(in_oklab,currentColor_35%,transparent)] hover:decoration-current focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                >
                  Undo
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

