function Badge({ tone, children }: { tone: string; children: ReactNode }) {
  return (
    <span
      aria-hidden="true"
      className="grid size-8 shrink-0 place-items-center rounded-full bg-[color-mix(in_oklab,var(--tone)_14%,transparent)] text-[var(--tone)]"
      style={{ "--tone": tone } as CSSProperties}
    >
